actions.script:
import java.util.Calendar
registerList = []
seqList = []
grandSalesValue = 0G
// ---- resolve the date window ----
def nowTs = ec.user.nowTimestamp
def fromTs = null; def thruTs = null
periodLabel = 'All dates'
if (period == 'thisMonth' || period == 'lastMonth') {
    def cal = Calendar.getInstance(ec.user.timeZone); cal.setTime(nowTs)
    cal.set(Calendar.DAY_OF_MONTH, 1); cal.set(Calendar.HOUR_OF_DAY, 0)
    cal.set(Calendar.MINUTE, 0); cal.set(Calendar.SECOND, 0); cal.set(Calendar.MILLISECOND, 0)
    if (period == 'lastMonth') cal.add(Calendar.MONTH, -1)
    fromTs = new java.sql.Timestamp(cal.getTimeInMillis())
    def c2 = (Calendar) cal.clone(); c2.add(Calendar.MONTH, 1)
    thruTs = new java.sql.Timestamp(c2.getTimeInMillis() - 1)
    periodLabel = ec.l10n.format(fromTs, 'MMMM yyyy')
} else if (period == 'custom') {
    def parseDay = { s ->
        if (!s) return null
        def str = s.toString().trim().take(10)
        for (fmt in ["yyyy-MM-dd", "dd/MM/yyyy", "dd-MM-yyyy", "MM/dd/yyyy"]) {
            try { def b = ec.l10n.parseTimestamp(str, fmt); if (b) return b } catch (e) {}
        }
        return null
    }
    def fb = parseDay(fromDate); if (fb) fromTs = new java.sql.Timestamp(fb.getTime())
    def tb = parseDay(thruDate)
    if (tb) {
        def nextDay = Calendar.getInstance(ec.user.timeZone); nextDay.setTime(tb); nextDay.add(Calendar.DAY_OF_MONTH,1)
        thruTs = new java.sql.Timestamp(nextDay.timeInMillis - 1)
    }
    periodLabel = (fromTs ? ec.l10n.format(fromTs, 'dd-MM-yyyy') : 'start') + ' to ' + (thruTs ? ec.l10n.format(thruTs, 'dd-MM-yyyy') : 'now')
}
def hasDate = (fromTs != null || thruTs != null)
def inWindow = { d ->
    if (!hasDate) return true
    if (d == null) return false
    if (fromTs != null && d.compareTo(fromTs) < 0) return false
    if (thruTs != null && d.compareTo(thruTs) > 0) return false
    return true
}
def gapsOnly = (viewMode == 'gaps')
Set kotTransactionIds = []
if (kotOnly) {
    def access = ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').call()
    if (!access?.allowed || !access.organizationPartyId) return
    organizationPartyId = access.organizationPartyId
    def shopId = ec.service.sync().name('zenith.base.ShopServices.get#ActiveShopScope').call().activeShopId
    def linked = ec.entity.find('zenith.erp.pos.KotTransactionDetailView')
        .condition('kotOrganizationPartyId', organizationPartyId)
        .condition('transactionNumber', 'like', 'POS/%/%')
        .selectField('transactionId').distinct(true)
    if (shopId) linked.condition('facilityId', shopId)
    if (access.terminalRestricted) {
        linked.condition('terminalId', 'in', access.allowedTerminalIds ?: ['__NONE__'])
        linked.condition('operatorPartyId', ec.user.userAccount?.partyId ?: '__NONE__')
    }
    kotTransactionIds.addAll(linked.list()*.transactionId)
    if (!kotTransactionIds) return
}
def finder = ec.entity.find("zenith.erp.pos.PosTransaction").condition("transactionNumber", "like", "POS/%/%")
if (organizationPartyId) finder.condition("organizationPartyId", organizationPartyId)
def txns = finder.selectField("transactionId").selectField("transactionNumber").selectField("statusId").selectField("entryDate").selectField("completedDate")
    .selectField("grandTotal").selectField("organizationPartyId").list()
// Group by (organization + prefix) so two stores reusing the same number never collide.
def groups = [:]
for (t in txns) {
    def mtch = (t.transactionNumber =~ /^(POS\/.*)\/(\d+)$/)
    if (mtch.find()) {
        def prefix = mtch.group(1); def num = mtch.group(2) as int
        def org = t.organizationPartyId ?: '(none)'
        def key = org + '|' + prefix
        if (!groups.containsKey(key)) groups[key] = [org:org, prefix:prefix, nums:[:]]
        groups[key].nums[num] = t
    }
}
def orgNameCache = [:]
def orgNameOf = { org ->
    if (orgNameCache.containsKey(org)) return orgNameCache[org]
    def nm = org
    def o = ec.entity.find("mantle.party.Organization").condition("partyId", org).one()
    if (o?.organizationName) nm = o.organizationName
    orgNameCache[org] = nm; return nm
}
def lbl = [PtCompleted:'Sale issued', PtHeld:'Held (parked)', PtCreated:'Incomplete cart', PtVoided:'Voided']
for (key in groups.keySet().sort()) {
    def g = groups[key]; def numMap = g.nums; def orgNm = orgNameOf(g.org)
    // Numbers issued inside the date window define the block to show. No window => all issued.
    def inRange = numMap.keySet().findAll { n ->
        def t = numMap[n]
        (!kotOnly || kotTransactionIds.contains(t.transactionId)) && inWindow(t.completedDate ?: t.entryDate)
    }
    if (!inRange) continue
    def mn = inRange.min(); def mx = inRange.max()
    def big = (mx - mn) > 2000
    def c = [sale:0, held:0, inc:0, voided:0, gap:0]
    def seqSales = 0G
    for (int n = mn; n <= mx; n++) {
        def t = numMap[n]
        // Retail or another shop can consume a number in this same sequence.
        if (kotOnly && t && !kotTransactionIds.contains(t.transactionId)) continue
        def status = t ? t.statusId : 'GAP'
        if (status == 'PtCompleted') { c.sale++; seqSales += ((t.grandTotal ?: 0) as BigDecimal) }
        else if (status == 'PtHeld') c.held++
        else if (status == 'PtCreated') c.inc++
        else if (status == 'PtVoided') c.voided++
        else c.gap++
        if (!(big && status == 'PtCompleted') && (!gapsOnly || status == 'GAP')) {
            registerList.add([orgName: orgNm, fullNumber: g.prefix + '/' + String.format('%05d', n),
                statusLabel: (t ? (lbl[status] ?: status) : 'UNUSED - no bill issued'),
                entryDate: (t ? t.entryDate : null), amount: (t ? t.grandTotal : null)])
        }
    }
    grandSalesValue += seqSales
    seqList.add([orgName:orgNm, prefix:g.prefix, rangeText:String.format('%05d',mn) + ' to ' + String.format('%05d',mx),
        total:(kotOnly ? c.values().sum() : mx - mn + 1), sale:c.sale, held:c.held, inc:c.inc, voided:c.voided, gap:c.gap, salesValue:seqSales,
        note:(big ? 'Large sequence: individual sales not listed below' : '')])
}
